		fmt.Println("YES")
		return
	}

	for ta := 0; ta < a[1]; ta++ {
		tmp := a[2] - ta*a[4]
		if tmp == a[0] {
			fmt.Println("YES")
			return
		}
	}

	for tb := 0; tb < a[1]; tb++ {
		tmp := a[3] - tb*a[5]
		if tmp == a[0] {
			fmt.Println("YES")
			return
		}
	}

	for ta := 0; ta < a[1]; ta++ {
		for tb := 0; tb < a[1]; tb++ {
			tmp := (a[2] - ta*a[4]) + (a[3] - tb*a[5])
			if tmp == a[0] {
				fmt.Println("YES")
				return
			}
		}
	}

	fmt.Println("NO")
}

